// Catalog data model. In production this is seeded into Postgres via Prisma
// (see prisma/seed.ts); the storefront reads through src/lib/catalog.ts so the
// data source can be swapped without touching pages.

export type Category = {
  slug: string;
  name: string;
  tagline: string;
  description: string;
  image: string;
  order: number;
};

export type PersonalisationKind = "photo" | "text" | "photo+text" | "multi-photo" | "none"; // none = ready-made, no editor

export type Variant = {
  sku: string;
  name: string; // "8x8 Hardcover, 20 pages"
  price: number; // INR
  compareAt?: number;
};

export type Product = {
  slug: string;
  legacyPath?: string; // old shivamprinters.com URL (for 301 redirect map)
  category: string; // category slug
  name: string;
  shortName?: string;
  description: string;
  image: string;
  images?: string[]; // extra gallery angles
  badges?: string[];
  personalisation: PersonalisationKind;
  // Editor template: print area as fraction of a canvas with given aspect
  template: {
    aspect: number; // width / height of product face
    photoSlots: number;
    textFields: { key: string; label: string; max: number }[];
  };
  variants: Variant[];
  variantLabel?: string; // heading above the variant picker (default "Size"); editable in /admin/pricing
  tags: string[]; // used by gift landing pages
  rating: number;
  reviews: number;
  featured?: boolean;
};

